package com.asmj.marketplace.controller;
import com.asmj.marketplace.model.Role; import com.asmj.marketplace.model.UserAccount; import com.asmj.marketplace.product.*; import com.asmj.marketplace.repository.UserAccountRepository;
import jakarta.servlet.http.HttpSession; import java.security.Principal; import java.util.*; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller public class ProductComparisonController {
 private static final String KEY="asmjCompareProductIds"; private final ProductRepository products; private final UserAccountRepository users;
 public ProductComparisonController(ProductRepository products,UserAccountRepository users){this.products=products;this.users=users;}
 @GetMapping("/customer/compare") public String compare(HttpSession session,Principal principal,Model model){customer(principal);List<Product> list=ids(session).stream().map(id->products.findById(id).orElse(null)).filter(p->p!=null&&p.getStatus()==ProductStatus.ACTIVE).toList();model.addAttribute("products",list);return "customer/compare";}
 @PostMapping("/customer/compare/add/{id}") public String add(@PathVariable String id,HttpSession session,Principal principal,RedirectAttributes ra){customer(principal);Product p=products.findById(id).filter(x->x.getStatus()==ProductStatus.ACTIVE).orElse(null);if(p==null){ra.addFlashAttribute("errorMessage","This product is no longer available.");return "redirect:/products";}List<String> list=ids(session);if(!list.contains(id)){if(list.size()>=4){ra.addFlashAttribute("errorMessage","You can compare up to four products. Remove one before adding another.");return "redirect:/customer/compare";}list.add(id);}session.setAttribute(KEY,list);ra.addFlashAttribute("successMessage","Product added to comparison.");return "redirect:/customer/compare";}
 @PostMapping("/customer/compare/remove/{id}") public String remove(@PathVariable String id,HttpSession session,Principal principal){customer(principal);ids(session).remove(id);return "redirect:/customer/compare";}
 private UserAccount customer(Principal p){UserAccount u=users.findByEmailIgnoreCase(p.getName()).orElseThrow();if(u.getRole()!=Role.ROLE_CUSTOMER)throw new IllegalArgumentException("Customer account required.");return u;}
 @SuppressWarnings("unchecked") private List<String> ids(HttpSession s){Object v=s.getAttribute(KEY);if(v instanceof List<?> l)return (List<String>)l;List<String> l=new ArrayList<>();s.setAttribute(KEY,l);return l;}
}
